var i=[{title:`Частини штанги`,text:`Типове налаштування має гриф, диски, що на нього підходять, і замки, що тримають диски на місці за потреби. Порожній гриф може здаватися початківцю важким, а спеціальні грифи мають різну вагу та розміри. Записуйте загальну вагу, яку ви піднімаєте, разом із грифом, а не лише диски.`},{title:`Навіщо використовувати штангу`,text:`Малі диски дають змогу додавати навантаження точними кроками, а один гриф може тренувати кілька основних рухових патернів. Однак обидві руки тримають один зв’язаний гриф, і це підходить не кожному плечу чи зап’ясту. Гантелі, тренажери чи вправи з вагою тіла можуть бути кращим вибором, коли ваше обладнання, комфорт чи досвід обмежені.`},{title:`Стійка і налаштування безпеки`,text:`Для присідів виставте J-гачки на потрібну вам висоту і поставте запобіжні планки чи штифти там, де вони впіймають невдале повторення, водночас дозволяючи рухатися всією запланованою амплітудою. Для жиму лежачи використовуйте компетентного страхувальника чи належно налаштовані запобіжники. Відпрацюйте вхід у стійку та вихід із неї з порожнім грифом, перш ніж піднімати важкі навантаження.`},{title:`Навчіться, перш ніж навантажуватися`,text:`Практикуйте присід, нахил, жим чи тягу з легким опором, доки гриф не йтиме тією самою траєкторією кожне повторення. Закріплюйте диски за потреби, перевіряйте простір навколо і ніколи не припускайте, що лава, стійка чи імпровізована рама зловить гриф, що падає. Вам не потрібно перевіряти свій максимум на одне повторення, щоб розвивати силу як початківцю. Виконуйте підйоми зі штангою лише тоді, коли у вас є відповідні гриф і диски, стійка чи інше безпечне налаштування та достатньо місця. Якщо ви тренуєтеся самі без належних запобіжників або маєте обмеження на навантаження хребта, оберіть іншу вправу.`}];var l=[{label:`NSCA: безпека та основи силових тренувань`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Mayo Clinic: техніка силових тренувань (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`Позиційна заява ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var s={sections:i,sources:l};export{s as default,i as sections,l as sources};